function obtenirEtatAcces(jetonAppareil, ticketGoogle) {
  try {
    nettoyerSessionsExpireesCDQ_();

    const admin = obtenirAdministrateurPrincipal_();

    // Chaque ouverture repart verrouillée. Le jeton appareil ou une identité
    // Google vérifiée détermine seulement QUEL écran de sécurité afficher.
    effacerSessionTemporaireCouranteCDQ_();

    const jeton = String(jetonAppareil || '').trim();
    const uAppareil = lireUtilisateurDepuisJetonAppareilCDQ_(jeton);

    // Appareil déjà activé : aucune nouvelle connexion Google.
    if (uAppareil) {
      if (nip4DefiniUtilisateurCDQ_(uAppareil)) {
        return {
          versionBackend: CDQ_BACKEND_BUILD_,
          autorise:false,
          appareilConnu:true,
          doitDeverrouiller:true,
          typeConnexion:'nip4',
          email:uAppareil.email,
          role:uAppareil.role,
          biometriePermise:true,
          createur:uAppareil.email === admin,
          message:'Déverrouillez l’application.'
        };
      }

      if (uAppareil.email === admin) {
        return {
          versionBackend:CDQ_BACKEND_BUILD_, autorise:false,
          activationValidee:true, doitCreerNip:true,
          email:admin, role:'admin', createur:true,
          jetonActivation:creerJetonActivationCDQ_(uAppareil),
          message:'Choisissez votre NIP de créateur.'
        };
      }

      return {
        versionBackend: CDQ_BACKEND_BUILD_,
        autorise:false,
        appareilConnu:true,
        doitActiverNip:true,
        typeConnexion:'activation6',
        email:uAppareil.email,
        role:uAppareil.role,
        message:'Entrez votre clé d’activation à usage unique, puis choisissez votre NIP.'
      };
    }

    // V26.19 : aucun appareil connu. On affiche directement le formulaire
    // CDQ (courriel autorisé + code d’activation). Le compte Google sera choisi
    // séparément seulement lorsqu’un fichier Drive/Sheets/PDF en aura besoin.
    return {
      versionBackend: CDQ_BACKEND_BUILD_,
      autorise:false,
      connexionRequise:true,
      oublierJeton: !!jeton,
      typeConnexion:'activation6',
      emailSuggere:'',
      message:'Entrez votre adresse courriel autorisée et votre code d’activation à 6 chiffres.'
    };

    // Aucun appareil connu : l'identité vient UNIQUEMENT de Google Identity
    // Services. On ne dépend plus de Session.getActiveUser() ni de la page
    // de connexion Apps Script.
    const identiteGoogle = lireTicketGoogleCDQ_(ticketGoogle);
    if (!identiteGoogle) {
      return {
        versionBackend: CDQ_BACKEND_BUILD_,
        autorise:false,
        connexionGoogleRequise:true,
        oublierJeton: !!jeton,
        typeConnexion:'google',
        message:'Connectez votre compte Google pour continuer.'
      };
    }

    const uGoogle = trouverUtilisateurAutoriseParEmail_(identiteGoogle.email);
    if (!uGoogle) {
      supprimerTicketGoogleCDQ_(ticketGoogle);
      return {
        versionBackend: CDQ_BACKEND_BUILD_,
        autorise:false,
        connexionGoogleRequise:true,
        oublierJeton: !!jeton,
        typeConnexion:'google',
        message:'Ce compte Google n’est plus autorisé.'
      };
    }

    // Un utilisateur déjà inscrit qui change de téléphone n'a PAS besoin d'une
    // nouvelle clé d'activation : Google + son NIP recréent seulement le jeton
    // local du nouvel appareil.
    if (nip4DefiniUtilisateurCDQ_(uGoogle)) {
      const nouveauJeton = creerJetonAppareilCDQ_(uGoogle);
      supprimerTicketGoogleCDQ_(ticketGoogle);
      return {
        versionBackend: CDQ_BACKEND_BUILD_,
        autorise:false,
        appareilConnu:true,
        doitDeverrouiller:true,
        typeConnexion:'nip4',
        email:uGoogle.email,
        role:uGoogle.role,
        biometriePermise:true,
        createur:uGoogle.email === admin,
        jetonAppareil:nouveauJeton,
        message:'Entrez votre NIP à 4 chiffres.'
      };
    }

    if (uGoogle.email === admin) {
      supprimerTicketGoogleCDQ_(ticketGoogle);
      return {
        versionBackend:CDQ_BACKEND_BUILD_, autorise:false,
        activationValidee:true, doitCreerNip:true,
        email:admin, role:'admin', createur:true,
        jetonActivation:creerJetonActivationCDQ_(uGoogle),
        message:'Choisissez votre NIP à 4 chiffres.'
      };
    }

    // Première inscription d'un technicien : Google est déjà confirmé.
    // La clé à 6 chiffres est demandée une seule fois, puis elle est consommée.
    return {
      versionBackend: CDQ_BACKEND_BUILD_,
      autorise:false,
      doitActiverNip:true,
      connexionGoogleValidee:true,
      typeConnexion:'activation6',
      email:uGoogle.email,
      role:uGoogle.role,
      message:'Compte Google confirmé. Entrez maintenant votre clé d’activation à usage unique.'
    };
  } catch(e) {
    return {
      versionBackend: CDQ_BACKEND_BUILD_,
      autorise:false,
      connexionGoogleRequise:true,
      typeConnexion:'google',
      message:e && e.message ? e.message : String(e)
    };
  }
}

function connecterAvecCodeAccesVerrouille_(email, code, ticketGoogle, jetonAppareil) {
  email = normaliserEmailCDQ_(email);
  code = String(code || '').trim();

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Adresse courriel invalide.');
  if (!codeAccesValideCDQ_(code)) throw new Error('Le code d’activation doit contenir 6 chiffres.');

  const identiteActivation = verifierIdentiteActivationCDQ_(email, ticketGoogle, jetonAppareil);

  const blocage = verifierBlocageConnexionCDQ_(email);
  if (blocage.bloque) {
    throw new Error('Trop de tentatives. Attendez 10 minutes avant de réessayer.');
  }

  const u = trouverUtilisateurAutoriseParEmail_(email);
  if (!u || !codeDefiniUtilisateurCDQ_(u) || !verifierCodeUtilisateurCDQ_(u, code)) {
    const echec = enregistrerEchecConnexionCDQ_(email);
    if (echec.bloque) throw new Error('Trop de tentatives. Accès temporairement bloqué pendant 10 minutes.');
    if (u && !codeDefiniUtilisateurCDQ_(u)) {
      if (nip4DefiniUtilisateurCDQ_(u)) {
        throw new Error('Ce code à 6 chiffres a déjà été utilisé. Déverrouillez plutôt avec votre NIP à 4 chiffres.');
      }
      throw new Error('Aucun code d’activation valide. Demandez à l’administrateur de générer un nouveau code.');
    }
    throw new Error('Adresse courriel ou code d’activation incorrect.');
  }

  effacerEchecsConnexionCDQ_(email);

  // Le code 6 chiffres est consommé IMMÉDIATEMENT.
  revoquerSessionsUtilisateur_(email);
  const jetonActivation = creerJetonActivationCDQ_(u);
  consommerCodeActivationCDQ_(email);
  if (identiteActivation.type === 'google') supprimerTicketGoogleCDQ_(ticketGoogle);

  return {
    autorise: false,
    activationValidee: true,
    doitCreerNip: true,
    email: u.email,
    role: u.role,
    jetonActivation: jetonActivation,
    message: 'Code accepté. Choisissez maintenant votre NIP à 4 chiffres.'
  };
}

