function reprendreActivationCDQ(jetonActivation) {
  const a = lireJetonActivationCDQ_(jetonActivation);
  if (!a) throw new Error('Cette activation a expiré. Demandez un nouveau code à 6 chiffres à l’administrateur.');
  const u = trouverUtilisateurAutoriseParEmail_(a.email);
  if (!u) throw new Error('Accès retiré par l’administrateur.');
  return {autorise:false, activationValidee:true, doitCreerNip:true,
    email:u.email, role:u.role, jetonActivation:String(jetonActivation),
    expirationActivation:a.expiresAt};
}

function restaurerSessionApresBiometrie(jetonAppareil) {
  jetonAppareil = String(jetonAppareil || '').trim();
  if (!jetonAppareil) throw new Error('Cet appareil n’est pas enregistré.');

  const u = lireUtilisateurDepuisJetonAppareilCDQ_(jetonAppareil);
  if (!u) throw new Error('Cet appareil n’est plus autorisé.');
  if (!nip4DefiniUtilisateurCDQ_(u)) throw new Error('Configurez d’abord votre NIP à 4 chiffres.');

  lierCleTemporaireCDQ_(u); // compatibilité seulement
  const jetonSession = creerSessionRpcCDQ_(u);
  return cdqStartupCachedV2527_({ autorise:true, email:u.email, role:u.role, jetonSession:jetonSession });
}

