function definirNip4ApresActivation(email, jetonActivation, nip, confirmation) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(15000)) throw new Error('Une vérification est déjà en cours. Réessayez dans un instant.');
  try { return definirNip4ApresActivationVerrouille_(email, jetonActivation, nip, confirmation); }
  finally { lock.releaseLock(); }
}

function definirNip4ApresActivationVerrouille_(email, jetonActivation, nip, confirmation) {
  email = normaliserEmailCDQ_(email);
  nip = String(nip || '').trim();
  confirmation = String(confirmation || '').trim();

  if (!nip4ValideCDQ_(nip)) throw new Error('Le NIP doit contenir exactement 4 chiffres.');
  if (nip !== confirmation) throw new Error('Les deux NIP ne correspondent pas.');

  const activation = lireJetonActivationCDQ_(jetonActivation);
  if (!activation || activation.email !== email) {
    throw new Error('Activation expirée. Demandez un nouveau code à 6 chiffres à l’administrateur.');
  }

  const uAvant = trouverUtilisateurAutoriseParEmail_(email);
  if (!uAvant) throw new Error('Utilisateur introuvable.');

  sauvegarderNip4UtilisateurCDQ_(email, nip);

  const u = trouverUtilisateurAutoriseParEmail_(email);
  const jetonAppareil = creerJetonAppareilCDQ_(u);

  // La clé temporaire Apps Script est facultative depuis V21.58. Elle est
  // conservée comme compatibilité lorsqu'elle existe, mais les techniciens
  // connectés par Google Identity Services utilisent la session RPC.
  lierCleTemporaireCDQ_(u);
  const jetonSession = creerSessionRpcCDQ_(u);

  PropertiesService.getScriptProperties().deleteProperty(activation.cle);

  return {
    autorise:true,
    email:u.email,
    role:u.role,
    jetonAppareil:jetonAppareil,
    jetonSession:jetonSession,
    nipConfigure:true
  };
}

function deverrouillerAvecNip(jetonAppareil, nip) {
  jetonAppareil = String(jetonAppareil || '').trim();
  nip = String(nip || '').trim();

  if (!jetonAppareil) throw new Error('Cet appareil n’est pas encore enregistré.');
  if (!nip4ValideCDQ_(nip)) throw new Error('Entrez votre NIP à 4 chiffres.');

  const u = lireUtilisateurDepuisJetonAppareilCDQ_(jetonAppareil);
  if (!u) throw new Error('Cet appareil n’est plus autorisé. Reconnectez-vous avec un nouveau code à 6 chiffres.');

  const blocage = verifierBlocageConnexionCDQ_(u.email);
  if (blocage.bloque) throw new Error('Trop de tentatives. Attendez 10 minutes avant de réessayer.');

  if (!nip4DefiniUtilisateurCDQ_(u) || !verifierNip4UtilisateurCDQ_(u, nip)) {
    const echec = enregistrerEchecConnexionCDQ_(u.email);
    if (echec.bloque) throw new Error('Trop de tentatives. NIP temporairement bloqué pendant 10 minutes.');
    throw new Error('NIP incorrect.');
  }

  effacerEchecsConnexionCDQ_(u.email);
  lierCleTemporaireCDQ_(u); // compatibilité seulement
  const jetonSession = creerSessionRpcCDQ_(u);

  return cdqStartupCachedV2527_({ autorise:true, email:u.email, role:u.role, jetonSession:jetonSession });
}

function trouverUtilisateurAutoriseParEmail_(email) {
  email = normaliserEmailCDQ_(email);
  if (!email) return null;
  const u = obtenirUtilisateursAutorises_().find(function(x){ return x.email === email; });
  return u || null;
}

